INSERT [dbo].[Surgerys] ([Id], [Name], [ShortName], [SurgeryTypeId], [RegularFee], [Discount], [TotalFee], [Description]) VALUES (1002, N'Breast augmentation surgery ', N'BAS', 1002, CAST(50000 AS Decimal(18, 0)), CAST(50000 AS Decimal(18, 0)), CAST(45000 AS Decimal(18, 0)), N'Hurley Medical Center offers breast augmentation surgery for reconstructive purposes after breast cancer surgery (for example), to correct a breast defect, to increase breast size, or to achieve a younger, more natural appearance. Hurley’s plastic surgeons and surgical team will thoroughly answer your questions, address any concerns or apprehension you may have, and help you decide if breast augmentation surgery is right for you.')
INSERT [dbo].[Surgerys] ([Id], [Name], [ShortName], [SurgeryTypeId], [RegularFee], [Discount], [TotalFee], [Description]) VALUES (1003, N'Breast reduction surgery ', N'BRS', 1002, CAST(20000 AS Decimal(18, 0)), CAST(5000 AS Decimal(18, 0)), CAST(15000 AS Decimal(18, 0)), N'Hurley Medical Center offers breast reduction surgery to decrease breast size and lift the breasts. Hurley’s plastic surgeons and surgical team works with you to determine your goals and desired expectations for breast reduction, and to help you decide if breast reduction surgery is right for you.')
